{"policy":"permit (
    principal is User,
    action == Action::"verifyPrescription",
    resource is Prescription
)
when {
    (principal.roles.contains(Role::"StaffPharmacist") ||
     principal.roles.contains(Role::"PharmacistInCharge")) &&
    (resource.status == PrescriptionStatus::"Received" ||
     principal.roles.contains(Role::"Exception") ||
     context.refillsRemainingCrossesThreshold)
};

forbid (
    principal is User,
    action == Action::"verifyPrescription",
    resource is Prescription
)
when {
    (principal.roles.contains(Role::"StaffPharmacist") ||
     principal.roles.contains(Role::"PharmacistInCharge")) &&
    resource.status == PrescriptionStatus::"OutsideReceived" &&
    !principal.roles.contains(Role::"Exception") &&
    !context.refillsRemainingCrossesThreshold
};"}
